INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'Biology', 'Unit 3', 'Molarum Grade 10 — Biology Biochemical Molecules', 'Source-grounded Molarum Grade 10 Biology questions for Biochemical Molecules.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('866ac180-02df-4bd9-8fe3-ce1c8fcbc9f5'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'Why water is considered a biochemical molecule?', 'It is the main solvent for biochemical reactions.', 'Water''s polarity makes it an excellent solvent for ionic and polar substances, enabling metabolic reactions.', 0),('e13084cb-c100-49b3-879a-1b4e57495040'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'What typical properties of water do you know?', 'Water polarity allows hydrogen bonding and dissolves many substances.', 'Water''s polarity enables hydrogen bonding, giving it properties like high solubility and high specific heat.', 1),('4f460f35-f517-4169-8f6d-d94985c2d6a0'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'What is the primary reason water has a bent molecular shape?', 'It has a bent shape because oxygen has two lone pairs, giving the molecule a V shape.', 'The two lone pairs on the oxygen atom repel bonding pairs, producing a bent geometry.', 2),('33bba12f-1574-4a72-8fb9-f6ee734dbfe0'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'Which process demonstrates how water moves up a plant stem due to cohesion and adhesion?', 'Both cohesion and adhesion enabling water transport in plants', 'Cohesion and adhesion work together to produce capillary action that helps water rise in xylem.', 3),('3ea821a1-6f4d-417d-8f61-db1e014ffac6'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'In a hydration shell around a cation like Na+, which part of the water molecule primarily orients toward the ion?', 'Water oxygen atoms face the cation (e.g., Na+).', 'The partially negative oxygen atoms face the positively charged ion, stabilizing the ion in solution.', 4),('9caaf39a-2df5-44fd-8ef7-aebdbeb087ee'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'true_false', 'Water is a polar molecule.', 'True', 'Water has a partial negative charge on the oxygen and partial positive charges on the hydrogen, giving it polarity.', 5),('d6bd6f4b-e9e7-4dc5-8b3a-16a54da88876'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'Name two biological macromolecules formed by polymerization.', 'Proteins and nucleic acids.', 'Proteins (polypeptides) and nucleic acids (DNA/RNA) are major polymeric biomolecules.', 6),('cc78c881-08c7-4a27-8bed-4dfa127e4009'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'Explain how enzymes act as biological catalysts in cells.', 'Enzymes speed up reactions by lowering activation energy and providing a specific active site; they are not consumed in the reaction.', 'Enzymes bind substrates at active sites, stabilize transition states, and lower the energy barrier.', 7),('d6fae94b-e65a-4478-8717-e127ad8c368e'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'Calculate the molarity of a solution prepared by dissolving 5.0 g of glucose (C6H12O6, molar mass 180.16 g/mol) in enough water to make 250 mL of solution. Provide the answer in M (mol/L).', '0.111 mol/L', 'Moles of glucose = 5.0 g / 180.16 g/mol = 0.0278 mol. Volume = 0.250 L. Molarity = 0.0278 mol / 0.250 L = 0.111 M.', 8),('e403a754-7ebf-4fb5-8472-28f2fa00be0a'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'Dilute 0.500 L of a 2.00 M NaCl solution to 1.000 L. What is the final molarity in M? Show the method and final unit.', '1.00 M', 'Using M1V1 = M2V2, M2 = (2.00 M × 0.500 L) / 1.000 L = 1.00 M.', 9),('80f6ae7d-b91d-4807-8c97-3ec9af350f09'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'Why water is considered as a biochemical molecule?', 'Because it participates in chemical reactions and acts as a solvent in living organisms', 'Water participates in hydrolysis and condensation reactions, and serves as the medium in which many biochemical reactions occur.', 10),('65b1031d-f203-423f-8061-7a7d3838102b'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'Which property explains water''s high surface tension and capillary rise?', 'Hydrogen bonding between water molecules', 'Hydrogen bonding creates cohesion among water molecules, leading to high surface tension and the ability for capillary action.', 11),('08cb1411-016c-4b32-8903-b1734f9df0f3'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'In a water molecule, what is the approximate shape?', 'Bent (V-shaped)', 'Water has a bent shape with an angle of about 104.5 degrees due to the lone pairs on oxygen.', 12),('07626460-3e28-4540-847e-0b68446fcb22'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'When NaCl dissolves in water, what happens to the ions?', 'Ions are surrounded by water molecules (hydration)', 'Ions become hydrated in solution as water molecules surround them, allowing the salt to dissolve.', 13),('515efacf-0047-46c6-8c34-8e3a09a78783'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'Which statement best describes cohesion in water?', 'Water molecules stick to each other', 'Cohesion is the attraction between water molecules; adhesion is the attraction to other surfaces.', 14),('fe59b8d1-1513-4c5f-8791-d4dae6992979'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'true_false', 'Water is a universal solvent.', 'True', 'Water dissolves many substances, enabling biochemical reactions in living organisms.', 15),('fe3204a0-9664-4ed3-8277-93f744df1229'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'Name two biomolecule categories that are essential for energy storage.', 'carbohydrates and lipids', 'Carbohydrates and lipids are primary energy storage biomolecules in living systems.', 16),('7583cf05-2c49-4bc1-85af-f87bc2b33b84'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'Name one biomolecule that is a polymer of amino acids.', 'proteins', 'Proteins are polymers formed by linking amino acids.', 17),('1649d647-f9a8-4ca8-8d82-aacf11f54f47'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'What is the mass of 2.0 moles of water (H2O)?', '36.03 g', 'Mass = number of moles × molar mass. Molar mass of H2O is 18.015 g/mol. 2.0 mol × 18.015 g/mol = 36.03 g.', 18),('885bcb15-fa96-44ec-8515-ccbe531d658d'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'If 0.100 moles of glucose (C6H12O6) are dissolved in 1.00 L of solution, what is the molarity of the glucose solution?', '0.100 M', 'Molarity M = n/V. n = 0.100 mol, V = 1.00 L, so M = 0.100 mol/L (0.1 M).', 19),('84646107-e7d8-480a-8c84-6b2c2cd9ea7b'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'Why is water considered a biochemical molecule?', 'A) It is the universal solvent for most biochemical reactions.', 'Water''s polarity allows it to dissolve many substances and participate in hydrolysis and condensation reactions in biology.', 20),('e41b2c7d-e65c-4bb5-8805-e166180b7771'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'Which property of water is most responsible for its high specific heat capacity in biological systems?', 'B) Hydrogen bonding between water molecules', 'Hydrogen bonds allow water to absorb a lot of heat before increasing in temperature, stabilizing body temperatures.', 21),('ff96c42b-420c-4c12-8351-d1b7b7618a92'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'In a water molecule, which element is the central atom?', 'B) Oxygen', 'Oxygen is the central atom in H2O with two hydrogen atoms bonded to it, giving the molecule a bent shape.', 22),('83b83c5a-eac4-40c4-89f2-88ba71e9ac03'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'Which process describes water molecules sticking to other surfaces (like glass)?', 'B) Adhesion', 'Adhesion is water''s tendency to cling to surfaces, while cohesion refers to water sticking to itself.', 23),('8a51adef-3932-422d-8eeb-1ca308ed5ae4'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'Which biomolecule is primarily used for long-term energy storage in animals?', 'C) Lipids', 'Lipids store energy efficiently and can provide long-term energy reserves.', 24),('ddad3e00-24aa-4ad4-8fa8-7959c234e770'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'true_false', 'Water molecules orient around dissolved ions due to their polar nature.', 'True', 'Polarity causes hydration shells around ions in solution.', 25),('10630178-05f7-40d0-8788-6bd6a2a7f2a9'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'Explain in one sentence why water is considered a biochemical molecule.', 'Water is a biochemical molecule because of its polarity and hydrogen bonding, which enable many biochemical reactions and solvent properties.', 'Water’s polarity allows dissolution of substances and participation in hydrolysis/condensation reactions.', 26),('f4c36e34-3cd6-43ba-8fae-0b97662d5090'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'Name two properties of water that support life and give one biological implication for each.', 'Polarity leading to solvent capability; Hydrogen bonding leading to high surface tension/thermal stability.', 'Polarity enables dissolution of ions and molecules; hydrogen bonding contributes to cohesion and thermal stability.', 27),('4d6773e6-555a-4c23-85d5-66352b1c27a8'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'A student dissolves 5.00 g of glucose (C6H12O6, molar mass = 180.16 g/mol) in water to make a final solution volume of 250.0 mL. What is the molarity (in mol/L) of the glucose in this solution? Show all steps and provide the final unit.', '0.111 M', 'moles of glucose = 5.00 g / 180.16 g/mol = 0.0278 mol; volume=0.250 L; M = 0.0278 / 0.250 = 0.111 M', 28),('669c1df5-bc45-4d8b-8fbe-039bd029fc5c'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'A solution is prepared by dissolving NaCl to make 0.50 L of a 0.150 M solution. How many moles of NaCl are present? Provide the calculation and final unit (moles).', '0.075 mol', 'moles = M × V = 0.150 mol/L × 0.50 L = 0.075 mol', 29),('af065264-8b58-4823-8753-a9036bde89e0'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'Based on Unit 3, which statement best describes water''s typical properties in biology?', 'Water is a polar molecule that can dissolve many substances', 'Water''s polarity makes it an effective solvent for many biological molecules.', 30),('3e7ab41b-d164-441a-85e0-8e59e888e81a'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'Which statement explains why water is considered a biochemical molecule?', 'It participates in metabolic reactions and is essential for life', 'Water acts as solvent and reactant/product in many biological processes.', 31),('9886eb20-6be2-4d13-8bd2-2227202d8412'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'In one water molecule (H2O), how many hydrogen atoms are present relative to the oxygen atom? Provide the ratio and final unit.', '2:1 (H:O); dimensionless ratio', 'A water molecule consists of two hydrogen atoms bonded to one oxygen atom.', 32),('01c7653e-26ee-43b6-83cf-a869858ccc7d'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'Which statement best explains why water has high surface tension?', 'Water molecules form hydrogen bonds with each other, creating cohesion at the surface', 'Cohesion via hydrogen bonding leads to a high surface tension at the air-water interface.', 33),('e41db307-4d49-4ba4-864f-3fca2794d90b'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'When water dissolves a cation such as Na+, which part of the water molecule orients toward the ion?', 'The oxygen atom (negative side) points toward the cation', 'Water is polar; the oxygen end (partial negative charge) faces the positively charged ion.', 34),('dd29916c-119c-4321-8919-1a131667838d'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'Water has a high boiling point relative to many small molecules due to...', 'Hydrogen bonding between molecules (cohesion)', 'Hydrogen bonding between water molecules requires more energy to break, raising the boiling point.', 35),('5fbdcb88-a9d7-46af-8dcc-2abb0239d846'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'true_false', 'Water is essential for life because it acts only as a solvent and never participates in chemical reactions.', 'False', 'Water participates in hydrolysis and dehydration reactions, not just as a solvent.', 36),('0a8a4dcf-8dfe-41af-8acf-2e29c25ecdcf'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'Explain two ways water''s polarity enables its role as a biological solvent.', 'Water''s polarity (partial negative on O and partial positive on H) allows it to dissolve ionic compounds by forming hydration shells around ions and to dissolve polar molecules by orienting itself to separate charges; it also enables water to participate in hydrolysis reactions.', 'Polarity enables solvent action and participation in biochemical reactions.', 37),('118b44a5-58dd-45fb-8672-be8f62bdff38'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'Describe how water molecules orient around a dissolved salt ion, naming which ends interact with cations vs anions.', 'Oxygen ends (with partial negative charge) face toward cations, while hydrogen ends face toward anions.', 'Hydration shells form with opposite ends of water oriented toward ions according to charge.', 38),('1e0f584a-8db7-45aa-8564-94dac0173911'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'If you have 5 water molecules, how many hydrogen atoms are present in total? Provide method and final unit.', '10 hydrogen atoms (5 molecules × 2 H per molecule)', 'Each H2O molecule contains 2 hydrogen atoms, so 5 molecules have 5 × 2 = 10 H atoms.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
INSERT INTO public.choices (id, question_id, choice_text, is_correct, order_index) VALUES ('2cc22367-f403-4e64-8f49-32d8f87eb2de'::uuid, '866ac180-02df-4bd9-8fe3-ce1c8fcbc9f5'::uuid, 'It is the main solvent for biochemical reactions.', TRUE, 0),('4a7dd84b-72f8-4276-8f29-09de913004ad'::uuid, '866ac180-02df-4bd9-8fe3-ce1c8fcbc9f5'::uuid, 'It is formed by the reaction of hydrogen and oxygen only in cells.', FALSE, 1),('6bbb7cbe-7080-4b0d-8cef-1c96301acba8'::uuid, '866ac180-02df-4bd9-8fe3-ce1c8fcbc9f5'::uuid, 'It cannot dissolve ions.', FALSE, 2),('707305a1-81ff-4bc5-88b7-37e5dae1587f'::uuid, '866ac180-02df-4bd9-8fe3-ce1c8fcbc9f5'::uuid, 'It has no role in metabolism.', FALSE, 3),('3ece7392-02b8-4e9c-8dd8-36ac348193a6'::uuid, 'e13084cb-c100-49b3-879a-1b4e57495040'::uuid, 'Water is nonpolar and does not dissolve salts.', FALSE, 0),('73b3dd86-d3f2-4c25-8291-7d8e8d3322d2'::uuid, 'e13084cb-c100-49b3-879a-1b4e57495040'::uuid, 'Water polarity allows hydrogen bonding and dissolves many substances.', TRUE, 1),('79516650-4c6b-46dc-8fbc-4e282cac55aa'::uuid, 'e13084cb-c100-49b3-879a-1b4e57495040'::uuid, 'Water has no high specific heat capacity.', FALSE, 2),('ccfc1e0b-eb40-4ce1-8246-4041d1308db4'::uuid, 'e13084cb-c100-49b3-879a-1b4e57495040'::uuid, 'Water cannot act as a universal solvent.', FALSE, 3),('eea77fa4-0250-4ca1-873c-a55732cf5a8e'::uuid, '4f460f35-f517-4169-8f6d-d94985c2d6a0'::uuid, 'It is a linear molecule with two hydrogens and one oxygen.', FALSE, 0),('b891ae58-ee3f-4d6d-8424-df032c542a24'::uuid, '4f460f35-f517-4169-8f6d-d94985c2d6a0'::uuid, 'It has a bent shape because oxygen has two lone pairs, giving the molecule a V shape.', TRUE, 1),('0d3de52f-4e06-4022-8c1c-b823d4da9238'::uuid, '4f460f35-f517-4169-8f6d-d94985c2d6a0'::uuid, 'It is nonpolar and hydrophobic.', FALSE, 2),('7a97c832-991d-422c-8704-f689c015a697'::uuid, '4f460f35-f517-4169-8f6d-d94985c2d6a0'::uuid, 'It forms a single bond between hydrogen and oxygen.', FALSE, 3),('c610cd8c-7994-469b-8579-1090913d013a':